<script setup lang="ts">
import {onMounted,reactive,ref} from 'vue';
import {useRoute} from 'vue-router';
import {ElMessageBox} from 'element-plus';
import {Search,Refresh,Filter,Download} from '@element-plus/icons-vue';
import {request,post,queryString} from '@/utils/request';
import {usePermissions} from '@/store/modules/permission.store';
import {downloadWorkbook} from '@/utils/workbook';
import {date,yuan,channelNames} from '@/utils/format';
import PaymentDialog from '@/components/PaymentDialog.vue';
const permissions=usePermissions(),route=useRoute(),items=ref<any[]>([]),query=ref(''),status=ref(String(route.query.status||'')),page=ref(1),size=ref(20),total=ref(0),loading=ref(false),detail=ref<any>(),payment=ref<any>(),filterDialog=ref(false),dateRange=ref<string[]>([]);
const filters=reactive({kind:'',payer:'',channel:'',delivery:'',from:'',to:''});
const kinds:Record<string,string>={RECHARGE:'账户充值',PURCHASE:'购买设备',RENEW:'设备续费',ACCELERATION:'加速服务'};
const statuses:Record<string,string>={PENDING:'待支付',PAID:'已支付',CANCELLED:'已取消'};
const deliveries:Record<string,string>={NONE:'无需交付',PENDING:'待交付',PROCESSING:'交付中',DELIVERED:'已交付',FAILED:'交付失败'};
const fields:Record<string,string>={productName:'商品名称',zone:'适用专区',platform:'适用平台',region:'设备地域',area:'设备地区',specification:'设备规格',months:'购买时长（月）',quantity:'数量',deviceId:'设备编号',autoRenew:'自动续费'};
const snapshot=(row:any)=>typeof row.snapshot==='string'?JSON.parse(row.snapshot):row.snapshot||{};
async function load(){loading.value=true;try{const r=await request('/orders?'+queryString({query:query.value,status:status.value,page:page.value,size:size.value,...filters}));items.value=r.items;total.value=r.total;}finally{loading.value=false;}}
onMounted(load);
function apply(){filters.from=dateRange.value?.[0]||'';filters.to=dateRange.value?.[1]||'';page.value=1;filterDialog.value=false;load();}
function reset(){Object.assign(filters,{kind:'',payer:'',channel:'',delivery:'',from:'',to:''});dateRange.value=[];status.value='';query.value='';}
async function pay(row:any){payment.value=await post(`/orders/${row.id}/payment`);}
async function cancel(row:any){try{await ElMessageBox.confirm('取消这笔未支付订单？','取消订单');}catch{return;}await post(`/orders/${row.id}/cancel`);await load();}
async function refresh(row:any){const latest=await post(`/orders/${row.id}/refresh`);if(detail.value?.id===row.id)detail.value=latest;await load();}
async function showDetail(row:any){detail.value=await request('/orders/'+row.id);}
async function exportAll(){if(!permissions.can('order.export'))return;const all:any[]=[];for(let p=1;;p++){const r=await request('/orders/export?'+queryString({query:query.value,status:status.value,page:p,...filters}));all.push(...r.items);if(all.length>=r.total)break;}await downloadWorkbook('订单列表.xlsx',all.map(r=>({...r,kind:kinds[r.kind],paymentStatus:statuses[r.paymentStatus],deliveryStatus:deliveries[r.deliveryStatus],productName:snapshot(r).productName||'账户充值',quantity:snapshot(r).quantity||1,amount:yuan(r.amountCents),paid:r.paymentStatus==='PAID'?yuan(r.amountCents):'0.00',channel:channelNames[r.channel],paidAt:date(r.paidAt)})),{id:'订单号',kind:'订单类型',paymentStatus:'订单状态',deliveryStatus:'购买状态',productName:'商品名称',quantity:'数量',amount:'订单金额（元）',paid:'实付金额（元）',channel:'支付方式',payerName:'付款用户',paidAt:'付款时间'});}
function canPay(row:any){return permissions.can(row.kind==='RECHARGE'?'wallet.recharge':row.kind==='PURCHASE'?'device.buy':'device.renew');}
</script>
<template><section class="panel page-list"><h1 class="page-title">订单管理</h1><el-tabs v-model="status" @tab-change="page=1;load()"><el-tab-pane label="全部订单" name=""/><el-tab-pane v-for="(label,key) in statuses" :key="key" :label="label" :name="key"/></el-tabs><div class="toolbar"><el-button v-if="permissions.can('order.export')" :icon="Download" @click="exportAll">导出订单</el-button><el-input v-model="query" class="search" placeholder="请输入订单号" clearable @clear="page=1;load()" @keyup.enter="page=1;load()"/><el-button :icon="Search" @click="page=1;load()">搜索</el-button><el-button :icon="Filter" @click="filterDialog=true">筛选</el-button><el-button :icon="Refresh" aria-label="刷新订单" @click="load"/></div>
<el-table :data="items" v-loading="loading"><el-table-column prop="id" label="订单号" min-width="180" show-overflow-tooltip/><el-table-column label="订单类型" width="100"><template #default="{row}">{{kinds[row.kind]}}</template></el-table-column><el-table-column label="订单状态" width="100"><template #default="{row}"><el-tag :type="row.paymentStatus==='PAID'?'success':row.paymentStatus==='PENDING'?'warning':'info'">{{statuses[row.paymentStatus]}}</el-tag></template></el-table-column><el-table-column label="购买状态" width="100"><template #default="{row}">{{deliveries[row.deliveryStatus]}}</template></el-table-column><el-table-column label="商品名称" min-width="155"><template #default="{row}">{{snapshot(row).productName||'账户充值'}}</template></el-table-column><el-table-column label="数量" width="70"><template #default="{row}">{{snapshot(row).quantity||1}}</template></el-table-column><el-table-column label="订单金额" width="110"><template #default="{row}"><span class="order-amount">¥ {{yuan(row.amountCents)}}</span></template></el-table-column><el-table-column label="实付金额" width="110"><template #default="{row}">¥ {{row.paymentStatus==='PAID'?yuan(row.amountCents):'0.00'}}</template></el-table-column><el-table-column label="实付余额" width="110"><template #default="{row}">¥ {{row.channel==='balance'&&row.paymentStatus==='PAID'?yuan(row.amountCents):'0.00'}}</template></el-table-column><el-table-column label="支付方式" width="110"><template #default="{row}">{{channelNames[row.channel]}}</template></el-table-column><el-table-column label="付款用户" min-width="130"><template #default="{row}">{{row.payerName}}<div class="table-sub">{{row.payerUsername}}</div></template></el-table-column><el-table-column label="付款时间" min-width="175"><template #default="{row}">{{date(row.paidAt)}}</template></el-table-column><el-table-column label="操作" width="180" fixed="right"><template #default="{row}"><el-button link type="primary" @click="showDetail(row)">详情</el-button><template v-if="row.paymentStatus==='PENDING'"><el-button v-if="canPay(row)" link type="primary" @click="pay(row)">去支付</el-button><el-button link type="danger" @click="cancel(row)">取消</el-button></template></template></el-table-column><template #empty><el-empty description="暂无订单数据" :image-size="90"/></template></el-table><el-pagination v-model:current-page="page" v-model:page-size="size" :page-sizes="[20,50,100]" :total="total" layout="total,sizes,prev,pager,next,jumper" @current-change="load" @size-change="page=1;load()"/>
</section>
<el-dialog v-model="filterDialog" title="筛选" width="550px"><el-form label-width="95px"><el-form-item label="订单号"><el-input v-model="query" placeholder="请输入订单号"/></el-form-item><el-form-item label="付款用户"><el-input v-model="filters.payer" placeholder="请输入付款用户"/></el-form-item><el-form-item label="订单类型"><el-select v-model="filters.kind" clearable placeholder="全部"><el-option v-for="(label,key) in kinds" :key="key" :value="key" :label="label"/></el-select></el-form-item><el-form-item label="付款时间"><el-date-picker v-model="dateRange" type="daterange" value-format="YYYY-MM-DD" start-placeholder="开始日期" end-placeholder="结束日期" range-separator="~"/></el-form-item><el-form-item label="订单状态"><el-select v-model="status" clearable placeholder="全部"><el-option v-for="(label,key) in statuses" :key="key" :value="key" :label="label"/></el-select></el-form-item><el-form-item label="购买状态"><el-select v-model="filters.delivery" clearable placeholder="全部"><el-option v-for="(label,key) in deliveries" :key="key" :value="key" :label="label"/></el-select></el-form-item><el-form-item label="支付方式"><el-select v-model="filters.channel" clearable placeholder="全部"><el-option v-for="(label,key) in channelNames" :key="key" :value="key" :label="label"/></el-select></el-form-item></el-form><template #footer><el-button @click="reset">重置</el-button><el-button type="primary" @click="apply">确认筛选</el-button></template></el-dialog>
<el-dialog :model-value="Boolean(detail)" title="订单详情" width="780px" @close="detail=undefined"><template v-if="detail"><el-descriptions :column="2" border><el-descriptions-item label="订单号" :span="2">{{detail.id}}</el-descriptions-item><el-descriptions-item label="订单类型">{{kinds[detail.kind]}}</el-descriptions-item><el-descriptions-item label="支付方式">{{channelNames[detail.channel]}}</el-descriptions-item><el-descriptions-item label="订单金额">¥ {{yuan(detail.amountCents)}}</el-descriptions-item><el-descriptions-item label="实付金额">¥ {{detail.paymentStatus==='PAID'?yuan(detail.amountCents):'0.00'}}</el-descriptions-item><el-descriptions-item label="订单状态">{{statuses[detail.paymentStatus]}}</el-descriptions-item><el-descriptions-item label="购买状态">{{deliveries[detail.deliveryStatus]}}</el-descriptions-item><el-descriptions-item label="创建时间">{{date(detail.createdAt)}}</el-descriptions-item><el-descriptions-item label="付款时间">{{date(detail.paidAt)}}</el-descriptions-item></el-descriptions><h3 class="section-title">商品信息</h3><el-descriptions :column="2" border><template v-for="(label,key) in fields" :key="key"><el-descriptions-item v-if="snapshot(detail)[key]!==undefined&&snapshot(detail)[key]!==''" :label="label">{{typeof snapshot(detail)[key]==='boolean'?(snapshot(detail)[key]?'是':'否'):snapshot(detail)[key]}}</el-descriptions-item></template></el-descriptions><el-alert v-if="detail.failureReason" :title="detail.failureReason" type="error" :closable="false"/><div class="toolbar"><el-button v-if="detail.paymentStatus==='PENDING'" @click="refresh(detail)">刷新支付状态</el-button></div></template></el-dialog><PaymentDialog :order="payment" @close="payment=undefined" @paid="load"/>
</template>
